const { exec } = require\('child_process'\);
const util = require\('util'\);
const execPromise = util.promisify\(exec\);

\(async \(\) => {
  try {
    const { stdout } = await execPromise\('git log dev/current-changes --name-status --pretty=format:"COMMIT|%h|%an|%ad|%s" --date=iso'\);

    const fileStats = new Map\(\);
    let currentCommit = null;

    stdout.split\('\\n'\).forEach\(line => {
      if \(line.startsWith\('COMMIT|'\)\) {
        const parts = line.split\('|'\);
        currentCommit = {
          hash: parts[1],
          author: parts[2],
          date: parts[3],
          subject: parts[4]
        };
      } else if \(/^[MADR]\\t/.test\(line\)\) {
        const filePath = line.substring\(2\);

        if \(!fileStats.has\(filePath\)\) {
          fileStats.set\(filePath, {
            path: filePath,
            name: filePath.split\('/'\).pop\(\),
            modifyCount: 0,
            lastModifiedDate: '',
            lastModifiedBy: '',
            lastCommitHash: '',
            lastCommitMessage: ''
          }\);
        }

        const stat = fileStats.get\(filePath\);
        stat.modifyCount++;

        if \(!stat.lastModifiedDate\) {
          stat.lastModifiedDate = currentCommit.date;
          stat.lastModifiedBy = currentCommit.author;
          stat.lastCommitHash = currentCommit.hash;
          stat.lastCommitMessage = currentCommit.subject;
        }
      }
    }\);

    const files = Array.from\(fileStats.values\(\)\).sort\(\(a, b\) => b.modifyCount - a.modifyCount\);

    console.log\('Total files:', files.length\);
    console.log\('Total commits:', \(stdout.match\(/COMMIT\\|/g\) || []\).length\);
    console.log\('\\nTop 5 most modified files:'\);
    files.slice\(0, 5\).forEach\(f => {
      console.log\(`  - ${f.path}: ${f.modifyCount} modifications`\);
      console.log\(`    Last by: ${f.lastModifiedBy} at ${f.lastModifiedDate}`\);
    }\);
  } catch \(err\) {
    console.error\('Error:', err.message\);
  }
}\)\(\);
EOF)
